/*
 * Applies easing interpolation to camera script coordinates.
 */
// FUNCTION: FF7 0x0058f59d
int __cdecl BattleFx_ShivaApplyCameraEasing(int value, int easeParam)
{
    int iterIndex;
    int src;
    int count;

    src = value;
    if (easeParam > 0) {
        count = easeParam >> 8;
        for (iterIndex = 0; iterIndex < count; iterIndex++) {
            value = SinFixed(value / 4);
        }
    } else {
        easeParam = -easeParam;
        count = easeParam >> 8;
        value = 0x1000 - value;
        for (iterIndex = 0; iterIndex < count; iterIndex++) {
            value = SinFixed(value / 4);
        }
        value = 0x1000 - value;
    }
    count = (easeParam & 0xFF) + 1;
    value = value * count + src * (0x100 - count) >> 8;
    return value;
}

