// FUNCTION: FF7 0x0059005b
void __cdecl BattleFx_SummonShivaApplyForceFieldsToParticle(BattleFxShivaParticle *particle)
{
    BattleFxVector3 *auxVec;
    int entryIndex;
    BattleFxShivaForceField *pForceField;
    int shiftCount;
    int length;
    int dot;
    BattleFxVector3 *dirVec;

    pForceField = (BattleFxShivaForceField *)Gfx_GetPsxScratchpadPtr(0);
    dirVec = (BattleFxVector3 *)((int)pForceField + 8);
    auxVec = (BattleFxVector3 *)((int)dirVec + 0x10);
    entryIndex = 0;
    while (g_pBattleSummonShivaActiveForceFields[entryIndex].kind != BATTLE_SHIVA_FORCE_END) {
        if ((particle->forceMask & 1 << entryIndex) != 0) {
            switch (g_pBattleSummonShivaActiveForceFields[entryIndex].kind) {
            case BATTLE_SHIVA_FORCE_NONE:
                break;
            case BATTLE_SHIVA_FORCE_REPEL_ALONG_DIR:
                dirVec->x = particle->posX - g_pBattleSummonShivaActiveForceFields[entryIndex].centerX;
                dirVec->y = particle->posY - g_pBattleSummonShivaActiveForceFields[entryIndex].centerY;
                dirVec->z = particle->posZ - g_pBattleSummonShivaActiveForceFields[entryIndex].centerZ;
                while (abs(dirVec->x) > 32767 || (abs(dirVec->y) > 32767 || abs(dirVec->z) > 32767)) {
                    dirVec->x = (dirVec->x) / 2;
                    dirVec->y = (dirVec->y) / 2;
                    dirVec->z = (dirVec->z) / 2;
                    shiftCount++;
                }
                length = VectorNormalToSVector((int *)dirVec, (short *)pForceField);
                if (length > 0) {
                    dot = pForceField->forceX * g_pBattleSummonShivaActiveForceFields[entryIndex].dirX + pForceField->forceY * g_pBattleSummonShivaActiveForceFields[entryIndex].dirY + pForceField->forceZ * g_pBattleSummonShivaActiveForceFields[entryIndex].dirZ;
                    if (dot > 0) {
                        dot = (dot >> 8) / SqrtToInt(length);
                        particle->velocityX += (short)((g_pBattleSummonShivaActiveForceFields[entryIndex].dirX + pForceField->forceX) * dot >> 10);
                        particle->velocityY += (short)((g_pBattleSummonShivaActiveForceFields[entryIndex].dirY + pForceField->forceY) * dot >> 10);
                        particle->velocityZ += (short)((g_pBattleSummonShivaActiveForceFields[entryIndex].dirZ + pForceField->forceZ) * dot >> 10);
                    }
                }
                break;
            case BATTLE_SHIVA_FORCE_ATTRACT:
                dirVec->x = g_pBattleSummonShivaActiveForceFields[entryIndex].centerX - particle->posX;
                dirVec->y = g_pBattleSummonShivaActiveForceFields[entryIndex].centerY - particle->posY;
                dirVec->z = g_pBattleSummonShivaActiveForceFields[entryIndex].centerZ - particle->posZ;
                VectorNormalToSVector((int *)dirVec, (short *)pForceField);
                particle->velocityX += (short)(pForceField->forceX * g_pBattleSummonShivaActiveForceFields[entryIndex].dirX >> 12);
                particle->velocityY += (short)(pForceField->forceY * g_pBattleSummonShivaActiveForceFields[entryIndex].dirY >> 12);
                particle->velocityZ += (short)(pForceField->forceZ * g_pBattleSummonShivaActiveForceFields[entryIndex].dirZ >> 12);
                break;
            case BATTLE_SHIVA_FORCE_CONSTANT:
                particle->velocityX += g_pBattleSummonShivaActiveForceFields[entryIndex].dirX;
                particle->velocityY += g_pBattleSummonShivaActiveForceFields[entryIndex].dirY;
                particle->velocityZ += g_pBattleSummonShivaActiveForceFields[entryIndex].dirZ;
                break;
            case BATTLE_SHIVA_FORCE_VORTEX:
                dirVec->x = g_pBattleSummonShivaActiveForceFields[entryIndex].centerX - particle->posX;
                dirVec->y = g_pBattleSummonShivaActiveForceFields[entryIndex].centerY - particle->posY;
                dirVec->z = g_pBattleSummonShivaActiveForceFields[entryIndex].centerZ - particle->posZ;
                NormalizeVectorFixed((int *)dirVec, (int *)dirVec);
                auxVec->x = g_pBattleSummonShivaActiveForceFields[entryIndex].dirX;
                auxVec->y = g_pBattleSummonShivaActiveForceFields[entryIndex].dirY;
                auxVec->z = g_pBattleSummonShivaActiveForceFields[entryIndex].dirZ;
                CrossProductFixed12((VECTOR *)dirVec, (VECTOR *)auxVec, (VECTOR *)dirVec);
                particle->velocityX += (short)(dirVec->x >> 4);
                particle->velocityY += (short)(dirVec->y >> 4);
                particle->velocityZ += (short)(dirVec->z >> 4);
            }
        }
        entryIndex++;
    }
}

